# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

# ---
def make_student(last: str, first: str) -> Student:
    return Student("id-" + last, last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Axwell", "Rue")
        ]

    def test_sorted_by_last_name_and_split(self):
        self.assertEqual(
            seat_rows(self.students, 2),
            ["Row 1: Axwell, Rue | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_single_row_when_seats_exceed_students(self):
        rows = seat_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_same_last_name_sorted_by_first_name(self):
        pair = [make_student("Dunmere", "Piet"), make_student("Dunmere", "Anja")]
        self.assertEqual(
            seat_rows(pair, 2), ["Row 1: Dunmere, Anja | Dunmere, Piet"]
        )

    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 4)
